358	    /**
359	     * Normalizes an owner's address on create, supporting both the structured form
360	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
361	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
362	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
363	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
364	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
365	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
366	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
367	     * flat {@code address} when no structured line is given - is written onto the request so it is what
368	     * gets validated, compared, stored and returned. Running before the required-field check means an
369	     * address that is blank in both forms after normalization is rejected like a missing one.
370	     */
371	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
372	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
373	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
374	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
375	        ownerFieldsDto.setAddressLine1(line1);
376	        ownerFieldsDto.setAddressLine2(line2);
377	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
378	    }
379	
380	    /**
381	     * Composes the effective address, preferring the structured form: when {@code line1} is present
382	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
383	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
384	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
385	     * left for the required-field check to reject) when no structured line is supplied.
386	     */
387	    private static String composeAddress(String line1, String line2, String flat) {
388	        if (line1 != null && !line1.isBlank()) {
389	            if (line2 != null && !line2.isBlank()) {
390	                return line1 + " " + line2;
391	            }
392	            return line1;
393	        }
394	        return flat;
395	    }
396	
397	    /**
398	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
399	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
400	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
401	     * address is returned unchanged, making it safe to apply to stored values during comparison.
402	     */
403	    private static String canonicalAddress(String address) {
404	        if (address == null) {
405	            return null;
406	        }
407	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
408	        if (collapsed.isEmpty()) {
409	            return "";
410	        }
411	        String[] tokens = collapsed.split(" ");
412	        StringBuilder sb = new StringBuilder(collapsed.length());
413	        for (int i = 0; i < tokens.length; i++) {
414	            if (i > 0) {
415	                sb.append(' ');
416	            }
417	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
418	        }
419	        return sb.toString();
420	    }
421	
422	    /**
423	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
424	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
425	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
426	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
427	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
428	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
429	     * written back onto the request so it is what gets stored and returned. Any value that cannot
430	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
431	     * {@code telephone}.
432	     */
433	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
434	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
435	    }
436	
437	    /**
438	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
439	     * (400) naming {@code telephone} when it cannot form a valid number.
440	     */
441	    private static String toE164(String telephone) {
442	        if (telephone == null) {
443	            throw new InvalidOwnerFieldsException(List.of("telephone"));
444	        }
445	        boolean hasCountryCode = telephone.trim().startsWith("+");
446	        String digits = telephone.replaceAll("\\D", "");
447	        String countryCode;
448	        String national;
449	        if (hasCountryCode) {
450	            countryCode = matchCountryCode(digits);
451	            national = digits;
452	        } else {
453	            countryCode = "61";
454	            if (digits.startsWith("0")) {
455	                digits = digits.substring(1);
456	            }
457	            national = "61" + digits;
458	        }
459	        if (!national.matches("[0-9]{8,15}")) {
460	            throw new InvalidOwnerFieldsException(List.of("telephone"));
461	        }
462	        if (countryCode != null) {
463	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
464	            if (requiredLength != null
465	                && national.length() - countryCode.length() != requiredLength) {
466	                throw new InvalidOwnerFieldsException(List.of("telephone"));
467	            }
468	        }
469	        return "+" + national;
470	    }
471	
472	    /**
473	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
474	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
475	     * the number is not length-checked against a country.
476	     */
477	    private static String matchCountryCode(String digits) {
478	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
479	            .filter(digits::startsWith)
480	            .max(Comparator.comparingInt(String::length))
481	            .orElse(null);
482	    }
483	
484	    /**
485	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
486	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
487	     * (a deterministic function of the normalized last name and postcode, see
488	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
489	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
490	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
491	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
492	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
493	     *
494	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
495	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
496	     * deleted.
497	     *
498	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
499	     * is allowed through even when it lands in an existing household, so it is created as a declared
500	     * household member rather than rejected. The incoming telephone and email have already been
501	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
502	     * is derived the same way before comparison. A match results in a 409 response naming
503	     * {@code identityKey}.
504	     */
505	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
506	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
507	            return;
508	        }
509	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
510	        for (Owner existing : this.clinicService.findAllOwners()) {
511	            if (Boolean.TRUE.equals(existing.getDeleted())) {
512	                continue;
513	            }
514	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
515	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
516	                throw new DuplicateOwnerIdentityException(identityKey);
517	            }
518	        }
519	    }
520	
521	    /**
522	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
523	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
524	     * are expected to already be in their normalized (E.164, lower-cased) forms.
525	     */
526	    private static String identityKey(String telephone, String email, String householdId) {
527	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
528	    }
529	
530	    /**
531	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
532	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
533	     * the stored email is lower-cased, and the stored household id is used as-is.
534	     */
535	    private static String existingIdentityKey(Owner existing) {
536	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
537	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
538	        return identityKey(telephone, email, existing.getHouseholdId());
539	    }
540	
541	    private static String orEmpty(String value) {
542	        return value == null ? "" : value;
543	    }
544	
545	    /**
546	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
547	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
548	     */
549	    private static String normalizeExisting(String telephone) {
550	        try {
551	            return toE164(telephone);
552	        } catch (InvalidOwnerFieldsException ex) {
553	            return null;
554	        }
555	    }
556	
557	    /**
558	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
559	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
560	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
561	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
562	     */
563	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
564	        String city = ownerFieldsDto.getCity();
565	        int count = 0;
566	        for (Owner existing : this.clinicService.findAllOwners()) {
567	            if (city.equalsIgnoreCase(existing.getCity())) {
568	                count++;
569	            }
570	        }
571	        if (count >= MAX_OWNERS_PER_CITY) {
572	            throw new OwnerCityAtCapacityException(city);
573	        }
574	    }
575	
576	    /**
577	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
578	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
579	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
580	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
581	     */
582	    private void rejectDailyLimitReached(LocalDate registrationDate) {
583	        int count = 0;
584	        for (Owner existing : this.clinicService.findAllOwners()) {
585	            if (registrationDate.equals(existing.getRegistrationDate())) {
586	                count++;
587	            }
588	        }
589	        if (count >= MAX_OWNERS_PER_DAY) {
590	            throw new DailyOwnerLimitReachedException(registrationDate);
591	        }
592	    }
593	
594	    /**
595	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
596	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
597	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
598	     */
599	    private static String normalizeForComparison(String value) {
600	        if (value == null) {
601	            return "";
602	        }
603	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
604	    }
605	
606	    /**
607	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
608	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
609	     * written back onto the request so that is what gets stored and returned. A present but invalid
610	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
611	     */
612	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
613	        String email = ownerFieldsDto.getEmail();
614	        if (email == null) {
615	            return;
616	        }
617	        String trimmed = email.trim();
618	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
619	            throw new InvalidOwnerFieldsException(List.of("email"));
620	        }
621	        String normalized = trimmed.toLowerCase(Locale.ROOT);
622	        String domain = normalized.substring(normalized.indexOf('@') + 1);
623	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
624	            throw new InvalidOwnerFieldsException(List.of("email"));
625	        }
626	        ownerFieldsDto.setEmail(normalized);
627	    }
628	
629	    /**
630	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
631	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
632	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
633	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
634	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
635	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
636	     * as-is so it is stored and returned.
637	     */
638	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
639	        String postcode = ownerFieldsDto.getPostcode();
640	        if (postcode == null) {
641	            return;
642	        }
643	        if (!postcode.matches("[0-9]{4}")) {
644	            throw new InvalidOwnerFieldsException(List.of("postcode"));
645	        }
646	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
647	        if (range != null) {
648	            int value = Integer.parseInt(postcode);
649	            if (value < range[0] || value > range[1]) {
650	                throw new InvalidOwnerFieldsException(List.of("postcode"));
651	            }
652	        }
653	    }
654	
655	    /**
656	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
657	     * day. When the caller supplies no value it defaults to the server's current date; a value
658	     * provided in the request is kept. A supplied value later than the server's current date is
659	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
660	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
661	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
662	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
663	     * every value derived from the registration date is based on.
664	     */
665	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
666	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
667	        if (effective == null) {
668	            effective = LocalDate.now();
669	        }
670	        else if (effective.isAfter(LocalDate.now())) {
671	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
672	        }
673	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
674	    }
675	
676	    /**
677	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
678	     * forward, just like a weekend, until it reaches a non-holiday business day.
679	     */
680	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
681	        LocalDate.of(2026, 1, 1),
682	        LocalDate.of(2026, 1, 26),
683	        LocalDate.of(2026, 4, 25),
684	        LocalDate.of(2026, 12, 25),
685	        LocalDate.of(2026, 12, 28));
686	
687	    /**
688	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
689	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
690	     * is not a holiday is returned unchanged.
691	     */
692	    private static LocalDate toBusinessDay(LocalDate date) {
693	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
694	            date = date.plusDays(1);
695	        }
696	        return date;
697	    }
698	
699	    /**
700	     * Returns whether the given date falls on a Saturday or Sunday.
701	     */
702	    private static boolean isWeekend(LocalDate date) {
703	        return switch (date.getDayOfWeek()) {
704	            case SATURDAY, SUNDAY -> true;
705	            default -> false;
706	        };
707	    }
708	
709	    /**
710	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
711	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
712	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
713	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
714	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
715	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
716	     * pure function of region, telephone and last name.
717	     */
718	    private void assignCustomerCode(Owner owner) {
719	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
720	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
721	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
722	    }
723	
724	    /**
725	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
726	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
727	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
728	     * among them.
729	     */
730	    private String deduplicateCustomerCode(String customerCode) {
731	        Set<String> existing = new HashSet<>();
732	        for (Owner owner : this.clinicService.findAllOwners()) {
733	            if (owner.getCustomerCode() != null) {
734	                existing.add(owner.getCustomerCode());
735	            }
736	        }
737	        if (!existing.contains(customerCode)) {
738	            return customerCode;
739	        }
740	        int n = 2;
741	        while (existing.contains(customerCode + "-" + n)) {
742	            n++;
743	        }
744	        return customerCode + "-" + n;
745	    }
746	
747	    /**
748	     * Assigns the owner's {@code membershipNumber} on create, formatted
749	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the fiscal year of
750	     * the business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July, e.g. a
751	     * registration on 2026-08-03 falls in fiscal year 2027 and yields {@code 'NSW-1A2B3C4D-M27'}).
752	     * Assigned after {@link #assignCustomerCode} and once {@code registrationDate} has been
753	     * defaulted, so both inputs are present.
754	     */
755	    private void assignMembershipNumber(Owner owner) {
756	        String yy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
757	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
758	    }
759	
760	    /**
761	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
762	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
763	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
764	     */
765	    private void assignNamesakeCount(Owner owner) {
766	        String firstName = owner.getFirstName();
767	        String lastName = owner.getLastName();
768	        int count = 0;
769	        for (Owner existing : this.clinicService.findAllOwners()) {
770	            if (firstName.equalsIgnoreCase(existing.getFirstName())
771	                && lastName.equalsIgnoreCase(existing.getLastName())) {
772	                count++;
773	            }
774	        }
775	        owner.setNamesakeCount(count);
776	    }
777	
778	    /**
779	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
780	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
781	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
782	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
783	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
784	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
785	     * tenure, so the tenure bonus never applies on create.
786	     */
787	    private void assignMembership(Owner owner) {
788	        int points = 0;
789	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
790	            points += 2;
791	        }
792	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
793	            points += 1;
794	        }
795	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
796	            points += 2;
797	        }
798	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
799	            points += 3;
800	        }
801	        owner.setMembershipPoints(points);
802	        owner.setMembershipLevel(membershipLevelForPoints(points));
803	    }
804	
805	    /**
806	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
807	     * 4-5, and 4 for 6 or more points.
808	     */
809	    private int membershipLevelForPoints(int points) {
810	        if (points <= 1) {
811	            return 1;
812	        }
813	        if (points <= 3) {
814	            return 2;
815	        }
816	        if (points <= 5) {
817	            return 3;
818	        }
819	        return 4;
820	    }
821	
822	    /**
823	     * The tenure, in elapsed fiscal years, of a newly created owner. Tenure accrues from membership
824	     * over time, and a new owner has not been a member for any elapsed fiscal year yet, so this is
825	     * always {@code 0} on create (regardless of any backdated {@code registrationDate}).
826	     */
827	    private long tenureFiscalYears(Owner owner) {
828	        return 0L;
829	    }
830	
831	    /**
832	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
833	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
834	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
835	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
836	     * pre-existing owners for that day.
837	     */
838	    private void assignBulkSignupWarning(Owner owner) {
839	        LocalDate registrationDate = owner.getRegistrationDate();
840	        int count = 0;
841	        for (Owner existing : this.clinicService.findAllOwners()) {
842	            if (registrationDate.equals(existing.getRegistrationDate())) {
843	                count++;
844	            }
845	        }
846	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
847	    }
848	
849	    /**
850	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
851	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
852	     * possible duplicate when an existing owner shares its {@code lastName} (compared
853	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
854	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
855	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
856	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
857	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
858	     *
859	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
860	     * has deliberately opted into an existing household, so its shared last name and postcode are
861	     * expected rather than a suspected duplicate.
862	     */
863	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
864	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
865	            owner.setPossibleDuplicate(false);
866	            owner.setPossibleDuplicateOf(null);
867	            return;
868	        }
869	        String lastName = owner.getLastName();
870	        String postcode = owner.getPostcode();
871	        String telephone = owner.getTelephone();
872	        Integer matchId = null;
873	        if (postcode != null) {
874	            for (Owner existing : this.clinicService.findAllOwners()) {
875	                if (lastName.equalsIgnoreCase(existing.getLastName())
876	                    && postcode.equals(existing.getPostcode())
877	                    && !postcode.isBlank()
878	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
879	                    && existing.getId() != null
880	                    && (matchId == null || existing.getId() < matchId)) {
881	                    matchId = existing.getId();
882	                }
883	            }
884	        }
885	        owner.setPossibleDuplicate(matchId != null);
886	        owner.setPossibleDuplicateOf(matchId);
887	    }
888	
889	    /**
890	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
891	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
892	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
893	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
894	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
895	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
896	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
897	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
898	     * ({@link #assignHouseholdMembership}).
899	     */
900	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
901	        String postcode = ownerFieldsDto.getPostcode();
902	        if (postcode == null || postcode.isBlank()) {
903	            return null;
904	        }
905	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
906	        return shaHexUpper(lastName + "|" + postcode, 12);
907	    }
908	
909	    /**
910	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
911	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
912	     * every existing owner already carrying the same identifier. Runs after the owner's
913	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
914	     * Left {@code null} when the owner belongs to no household.
915	     */
916	    private void assignHouseholdMembership(Owner owner) {
917	        String householdId = owner.getHouseholdId();
918	        if (householdId == null || householdId.isBlank()) {
919	            owner.setHouseholdMemberCount(null);
920	            return;
921	        }
922	        int count = 1;
923	        for (Owner existing : this.clinicService.findAllOwners()) {
924	            if (householdId.equals(existing.getHouseholdId())) {
925	                count++;
926	            }
927	        }
928	        owner.setHouseholdMemberCount(count);
929	    }
930	
931	    /**
932	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
933	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
934	     * identifier, both stable functions of their inputs.
935	     */
936	    private static String shaHexUpper(String input, int length) {
937	        try {
938	            byte[] digest = MessageDigest.getInstance("SHA-256")
939	                .digest(input.getBytes(StandardCharsets.UTF_8));
940	            StringBuilder hex = new StringBuilder(digest.length * 2);
941	            for (byte b : digest) {
942	                hex.append(String.format("%02x", b));
943	            }
944	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
945	        } catch (NoSuchAlgorithmException ex) {
946	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
947	        }
948	    }
949	}
